common:
/* Shared native pagination: Blog/Guides reference; structural lists are never page buttons.
 * One owner for directory, archive, search and legacy data renderer controls. */
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination,.vf-data-pagination){display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:8px;margin-top:28px;padding:0!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination,.vf-data-pagination) :where(ul.page-numbers,.nav-links){display:flex!important;align-items:center!important;justify-content:center!important;flex-wrap:wrap!important;gap:8px!important;width:auto!important;min-width:0!important;min-height:0!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;list-style:none!important}
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination) ul.page-numbers>li{display:block!important;margin:0!important;padding:0!important;border:0!important;background:transparent!important;list-style:none!important}
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination) :is(a,span).page-numbers,
body.vf-front-contract-body #content .vf-data-pagination>a{display:inline-flex!important;align-items:center!important;justify-content:center!important;box-sizing:border-box!important;min-width:44px!important;min-height:44px!important;margin:0!important;padding:8px 12px!important;border:1px solid #d7e0d9!important;border-radius:7px!important;background:var(--vf-color-surface-strong)!important;color:var(--vf-color-text)!important;font-size:14px!important;font-weight:600!important;line-height:1.4!important;text-decoration:none!important;box-shadow:none!important}
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination) .page-numbers.current,
body.vf-front-contract-body #content .vf-data-pagination>a.is-current{border-color:var(--vf-color-primary)!important;background:var(--vf-color-primary)!important;color:var(--vf-color-on-primary)!important}
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination) span.page-numbers.dots{border-color:transparent!important;background:transparent!important;font-weight:400!important}
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination) a.page-numbers:hover,
body.vf-front-contract-body #content .vf-data-pagination>a:not(.is-current):hover{border-color:var(--vf-color-primary-border)!important;background:var(--vf-color-primary-soft)!important;color:var(--vf-color-text)!important}
body.vf-front-contract-body #content :where(.vf-theme-pagination,.navigation.pagination) a.page-numbers:focus-visible,
body.vf-front-contract-body #content .vf-data-pagination>a:focus-visible{outline:2px solid var(--vf-color-primary)!important;outline-offset:3px!important}
